test('invoiceTotals calculates subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const totals = invoiceTotals(invoice);
  // 2 * 8500 = 17000 (subtotal)
  // No discount = 0
  // VAT = 17000 * 21% = 3570
  // Total = 17000 - 0 + 3570 = 20570
  assert.deepEqual(totals, {
    subtotal: 17000,
    discount: 0,
    vat: 3570,
    total: 20570,
  });
});

