    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // 2 * 8500 + 3 * 9500 = 17000 + 28500 = 45500
  // No discount = 0
  // VAT = 45500 * 21% = 9555
  // Total = 45500 - 0 + 9555 = 55055
  assert.equal(totals.subtotal, 45500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 9555);
  assert.equal(totals.total, 55055);
});

