test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 2, unitPrice: 8500 }), 17000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('invoiceTotals calculates subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const totals = invoiceTotals(invoice);
  // 2 * 8500 = 17000 (subtotal)
  // No discount = 0
  // VAT = 17000 * 21% = 3570
  // Total = 17000 - 0 + 3570 = 20570
  assert.deepEqual(totals, {
    subtotal: 17000,
    discount: 0,
    vat: 3570,
    total: 20570,
  });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // 2 * 8500 + 3 * 9500 = 17000 + 28500 = 45500
  // No discount = 0
  // VAT = 45500 * 21% = 9555
  // Total = 45500 - 0 + 9555 = 55055
  assert.equal(totals.subtotal, 45500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 9555);
  assert.equal(totals.total, 55055);
});

