    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 50 }],
  }).value;
  const totals = invoiceTotals(invoice);
  // 2 * 8500 = 17000
  // Discount = 17000 * 50% = 8500
  // Amount after discount = 17000 - 8500 = 8500
  // VAT = 8500 * 21% = 1785
  // Total = 17000 - 8500 + 1785 = 10285
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 1785);
  assert.equal(totals.total, 10285);
});

