import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: ' c-002 ', // lowercase with spaces
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice rejects invalid terms', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
      terms: 'NET60',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );
});

test('invoiceTotals includes voucher in total', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 2, unitPrice: 8500, vatRate: 21, name: 'Design work', discountPercent: 0 }],
    voucher: { code: 'SAVE10', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 17000, VAT: 3570, Voucher: 1000
  // Total: 17000 + 3570 - 1000 = 19570
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.vat, 3570);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total, 19570);
});

test('applyVoucher applies voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = applyVoucher(invoice, { code: 'SAVE20', amount: 2000 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SAVE20');
  assert.equal(r.value.voucher.amount, 2000);
});

test('applyVoucher returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  assert.deepEqual(applyVoucher(issued, { code: 'SAVE20', amount: 2000 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('applyVoucher returns VOUCHER_EXISTS if voucher already applied', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 1000 }).value;

  assert.deepEqual(applyVoucher(withVoucher, { code: 'SAVE20', amount: 2000 }), {
    ok: false,
    error: 'VOUCHER_EXISTS',
  });
});

test('applyVoucher returns AMOUNT_INVALID for invalid amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
