    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // Line 1: 2 * 8500 = 17000, discount = 1700, after = 15300, VAT = 3213
  // Line 2: 2 * 9500 = 19000, discount = 3800, after = 15200, VAT = 3192
  // Subtotal = 36000, discount = 5500, VAT = 6405, total = 36000 - 5500 + 6405 = 36905
  assert.equal(totals.subtotal, 36000);
  assert.equal(totals.discount, 5500);
  assert.equal(totals.vat, 6405);
  assert.equal(totals.total, 36905);
});

test('invoiceTotals with VAT on multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', qty: 1, unitPrice: 980, vatRate: 21, name: 'Icon set', discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, unitPrice: 37, vatRate: 9, name: 'Printed flyer A4', discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 980, no discount, VAT = 980 * 21% = 205.8 -> 206
  // Line 2: 3700, no discount, VAT = 3700 * 9% = 333
  // Total = 980 + 3700 + 206 + 333 = 5219
  assert.equal(totals.subtotal, 4680);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 539);
  assert.equal(totals.total, 5219);
});

